import type { Bank } from "./types";

const bank: Bank = {
  questions: [
    { id: "fr-001", chapter: "1. Introduction to Indian Accounting Standards", prompt: "A company has prepared its financial statements under Ind AS for two years (it adopted voluntarily). Its net worth has since fallen to ₹90 crore and it is unlisted. Which statement is correct?", options: ["It may revert to Accounting Standards because its net worth is below the roadmap threshold", "It may revert to Accounting Standards only with the approval of the Tribunal", "It must continue to apply Ind AS; once adopted, Ind AS cannot be given up", "It may revert to Accounting Standards after three consecutive years below the threshold"], answer: 2, explanation: "Under the Companies (Ind AS) Rules, a company that once follows Ind AS (voluntarily or mandatorily) must keep following it; a fall in net worth does not permit reverting." },
    { id: "fr-002", chapter: "1. Introduction to Indian Accounting Standards", prompt: "An unlisted Indian company with net worth of ₹160 crore is a subsidiary of a listed Indian company that is required to apply Ind AS. For its own standalone financial statements, the subsidiary:", options: ["applies Accounting Standards, since its own net worth is below ₹250 crore", "must apply Ind AS, as the roadmap extends to subsidiaries of companies covered by it", "applies Accounting Standards but must give its parent an Ind AS reporting pack only", "may choose either framework, as subsidiaries are covered only on a voluntary basis"], answer: 1, explanation: "The roadmap applies Ind AS to holding, subsidiary, joint venture and associate companies of a covered company, regardless of their own net worth." },
    { id: "fr-003", chapter: "2. Conceptual Framework for Financial Reporting under Indian Accounting Standards (Ind AS)", prompt: "Which of the following is NOT an enhancing qualitative characteristic of useful financial information under the Conceptual Framework?", options: ["Materiality", "Comparability", "Verifiability", "Timeliness"], answer: 0, explanation: "Materiality is an entity-specific aspect of relevance (a fundamental characteristic); the four enhancing ones are comparability, verifiability, timeliness and understandability." },
    { id: "fr-004", chapter: "2. Conceptual Framework for Financial Reporting under Indian Accounting Standards (Ind AS)", prompt: "Which of the following is NOT a current value measurement basis described in the Conceptual Framework?", options: ["Amortised cost", "Fair value", "Value in use / fulfilment value", "Current cost"], answer: 0, explanation: "The Framework splits measurement into historical cost (which includes amortised cost) and current value (fair value, value in use/fulfilment value and current cost)." },
    { id: "fr-005", chapter: "2. Conceptual Framework for Financial Reporting under Indian Accounting Standards (Ind AS)", prompt: "As described in the Conceptual Framework, prudence:", options: ["requires losses to be recognised more readily than gains in every case", "supports neutrality and does not justify understating assets or income", "is an enhancing characteristic that may override faithful representation", "permits hidden reserves to be created whenever outcomes are uncertain"], answer: 1, explanation: "Prudence is caution under uncertainty that supports neutrality; it does not imply asymmetry or justify deliberate understatement or overstatement." },
    { id: "fr-006", chapter: "3. Ind AS on Presentation of General Purpose Financial Statements", prompt: "A manufacturing company (not a financial institution) pays interest of ₹40 lakh on a term loan and receives dividends of ₹6 lakh on investments. Under Ind AS 7, how are these classified?", options: ["Interest paid: operating or financing as a policy choice; dividends received: operating or investing", "Interest paid: operating; dividends received: operating", "Interest paid: financing; dividends received: investing", "Interest paid: financing; dividends received: operating"], answer: 2, explanation: "Ind AS 7 removes the IAS 7 choice for entities other than financial institutions: interest paid is financing and interest and dividends received are investing." },
    { id: "fr-007", chapter: "3. Ind AS on Presentation of General Purpose Financial Statements", prompt: "Profit before tax ₹50,00,000 includes depreciation ₹8,00,000, interest expense ₹4,00,000 and gain on sale of PPE ₹1,00,000. Trade receivables rose by ₹6,00,000, inventory fell by ₹3,00,000, trade payables fell by ₹2,00,000 and income tax paid was ₹9,00,000. Net cash from operating activities (non-financial entity) is:", options: ["₹43,00,000", "₹48,00,000", "₹51,00,000", "₹47,00,000"], answer: 3, explanation: "50 + 8 + 4 − 1 − 6 + 3 − 2 = 56 lakh before tax; less tax 9 = 47 lakh. Interest is added back because it is a financing outflow." },
    { id: "fr-008", chapter: "3. Ind AS on Presentation of General Purpose Financial Statements", prompt: "In Q1, a company earns pre-tax profit of ₹10 lakh and expects ₹40 lakh for the full year. Tax is 20% on the first ₹20 lakh of annual profit and 30% on the rest. Under Ind AS 34, Q1 tax expense is:", options: ["₹2,00,000", "₹2,50,000", "₹3,00,000", "₹2,75,000"], answer: 1, explanation: "Annual tax = 4 + 6 = 10 lakh on 40 lakh, an effective rate of 25%; Q1 tax = 10 lakh × 25% = 2.5 lakh." },
    { id: "fr-009", chapter: "3. Ind AS on Presentation of General Purpose Financial Statements", prompt: "A listed company prepares a condensed interim report for the half-year ended 30 September 2027 (financial year ends 31 March). Under Ind AS 34, the comparative balance sheet must be as at:", options: ["30 September 2026", "31 March 2027", "Both 30 September 2026 and 31 March 2027", "1 April 2026"], answer: 1, explanation: "Ind AS 34 requires the balance sheet at the end of the current interim period and as at the end of the immediately preceding financial year." },
    { id: "fr-010", chapter: "3. Ind AS on Presentation of General Purpose Financial Statements", prompt: "Which of the following requires presentation of a third balance sheet (as at the beginning of the preceding period) under Ind AS 1?", options: ["A change in the useful life of plant, applied from the current period", "A new Ind AS adopted prospectively under its transitional provisions", "A retrospective error restatement with a material effect on that opening balance sheet", "A change in accounting policy for which retrospective application is impracticable"], answer: 2, explanation: "A third balance sheet is needed only when a retrospective policy change, restatement or reclassification has a material effect on information in that opening balance sheet." },
    { id: "fr-011", chapter: "3. Ind AS on Presentation of General Purpose Financial Statements", prompt: "Which of the following items of OCI WILL be reclassified to profit or loss in a later period?", options: ["Remeasurement gains on a defined benefit plan", "Exchange differences on translating the net assets of a foreign operation", "Revaluation surplus on property, plant and equipment", "Fair value gains on equity instruments designated at FVOCI"], answer: 1, explanation: "Foreign operation translation differences are recycled on disposal; the other three are never reclassified to profit or loss." },
    { id: "fr-012", chapter: "3. Ind AS on Presentation of General Purpose Financial Statements", prompt: "Which of the following does NOT qualify as a cash equivalent under Ind AS 7?", options: ["A three-month bank deposit at acquisition, not subject to significant risk of change in value", "Redeemable preference shares acquired one month before their fixed redemption date", "Treasury bills with an original maturity of 90 days", "Highly liquid listed equity shares held for short-term trading"], answer: 3, explanation: "Equity investments are excluded from cash equivalents (their value can change significantly) unless they are, in substance, cash equivalents near a fixed redemption." },
    { id: "fr-013", chapter: "4. Ind AS on Measurement based on Accounting Policies", prompt: "A machine costing ₹20,00,000 bought on 1 April 2023 is depreciated straight-line over 10 years (nil residual). On 1 April 2026 the remaining useful life is reassessed as 4 years. Depreciation for 2026-27 is:", options: ["₹2,00,000", "₹5,00,000", "₹2,80,000", "₹3,50,000"], answer: 3, explanation: "A change in estimate is prospective: carrying amount 14 lakh (20 − 3 × 2) spread over the 4 remaining years = 3.5 lakh." },
    { id: "fr-014", chapter: "4. Ind AS on Measurement based on Accounting Policies", prompt: "Which of the following is a change in accounting estimate (not a change in accounting policy) under Ind AS 8?", options: ["Changing the inventory cost formula from FIFO to weighted average", "Changing from the cost model to the revaluation model for land", "Changing presentation of an expense from 'other expenses' to 'cost of materials consumed'", "Changing the depreciation method from written-down value to straight-line"], answer: 3, explanation: "Ind AS 16 states a change in depreciation method reflects a change in the expected pattern of consumption and is a change in estimate." },
    { id: "fr-015", chapter: "4. Ind AS on Measurement based on Accounting Policies", prompt: "Which of the following events after the reporting period (before approval of the financial statements) is an ADJUSTING event under Ind AS 10?", options: ["A fire that destroys a major plant after the reporting date", "Declaration of an equity dividend after the reporting date", "Settlement of a court case confirming the entity had a present obligation at the reporting date", "A sharp fall in the fair value of quoted investments after the reporting date"], answer: 2, explanation: "The court settlement provides evidence of a condition that existed at the reporting date; the others relate to conditions arising after it." },
    { id: "fr-016", chapter: "4. Ind AS on Measurement based on Accounting Policies", prompt: "An asset is traded in Market X (price ₹480, transaction costs ₹30, transport ₹20) and Market Y (price ₹470, transaction costs ₹10, transport ₹25). There is no principal market. Fair value under Ind AS 113 is:", options: ["₹445", "₹435", "₹460", "₹430"], answer: 0, explanation: "Most advantageous market is Y (net 435 vs 430); fair value is Y's price less transport only: 470 − 25 = 445. Transaction costs are not deducted from fair value." },
    { id: "fr-017", chapter: "4. Ind AS on Measurement based on Accounting Policies", prompt: "Which of the following is a Level 2 input under Ind AS 113?", options: ["Unadjusted quoted price for an identical asset in an active market", "The entity's own projected cash flows for an unlisted investment", "Quoted price for a similar asset in an active market", "Volatility estimated only from the entity's internal data"], answer: 2, explanation: "Level 2 inputs are observable but not Level 1 prices, such as quoted prices for similar assets in active markets." },
    { id: "fr-018", chapter: "4. Ind AS on Measurement based on Accounting Policies", prompt: "Land used as a factory site would be worth ₹8 crore in that use. Residential development is legally permitted and financially feasible; as vacant land for residential use it is worth ₹10 crore, but demolishing the factory would cost ₹1 crore. Fair value under Ind AS 113 is:", options: ["₹9 crore", "₹8 crore", "₹10 crore", "₹11 crore"], answer: 0, explanation: "Fair value reflects highest and best use from a market participant view: max(8, 10 − 1) = 9 crore, even if the entity keeps the current use." },
    { id: "fr-019", chapter: "5. Ind AS on Assets of the Financial Statements", prompt: "Raw material (5,000 kg) costs ₹200/kg; replacement cost is now ₹170/kg. The finished product made from it costs ₹900 per unit and has an NRV of ₹940 per unit. Raw material in inventory is measured at:", options: ["₹8,50,000", "₹10,00,000", "₹9,40,000", "₹9,00,000"], answer: 1, explanation: "Materials are not written down below cost if the finished goods they go into will sell at or above cost; 5,000 × 200 = 10 lakh." },
    { id: "fr-020", chapter: "5. Ind AS on Assets of the Financial Statements", prompt: "Fixed production overheads are ₹12,00,000; normal capacity is 60,000 units, but only 40,000 units were produced. Under Ind AS 2, the fixed overhead expensed as unallocated is:", options: ["Nil", "₹4,00,000", "₹8,00,000", "₹12,00,000"], answer: 1, explanation: "Absorption is based on normal capacity: 12 lakh / 60,000 = ₹20 per unit; 40,000 × 20 = 8 lakh in inventory, the balance 4 lakh is expensed." },
    { id: "fr-021", chapter: "5. Ind AS on Assets of the Financial Statements", prompt: "Plant is bought for ₹50,00,000. Dismantling at the end of its 5-year life will cost an estimated ₹10,00,000; the discount rate is 10% (1.1^5 = 1.61051). Initial cost of the plant under Ind AS 16 is:", options: ["₹60,00,000", "₹56,20,921", "₹50,00,000", "₹56,83,013"], answer: 1, explanation: "Present value of dismantling = 10,00,000 / 1.61051 = 6,20,921, added to cost: 50,00,000 + 6,20,921 = 56,20,921." },
    { id: "fr-022", chapter: "5. Ind AS on Assets of the Financial Statements", prompt: "Land under the revaluation model had a revaluation surplus of ₹3 lakh. A further revaluation now shows a decrease of ₹5 lakh. Under Ind AS 16, the decrease is recognised as:", options: ["₹5 lakh in profit or loss", "₹5 lakh in OCI, making the surplus negative", "₹3 lakh in OCI and ₹2 lakh in profit or loss", "₹2 lakh in OCI and ₹3 lakh in profit or loss"], answer: 2, explanation: "A decrease is charged to OCI only up to the existing surplus for that asset (3 lakh); the excess 2 lakh goes to profit or loss." },
    { id: "fr-023", chapter: "5. Ind AS on Assets of the Financial Statements", prompt: "Under the cost model, plant has a carrying amount of ₹4 lakh. Its decommissioning liability is re-estimated and decreases by ₹5 lakh. The accounting is:", options: ["Reduce the asset by ₹5 lakh, giving a negative carrying amount", "Recognise the entire ₹5 lakh in profit or loss", "Reduce the asset to nil and recognise ₹1 lakh in profit or loss", "Recognise ₹5 lakh in OCI as a revaluation surplus"], answer: 2, explanation: "Changes in the liability adjust the asset's cost under the cost model; a decrease beyond the carrying amount is taken to profit or loss." },
    { id: "fr-024", chapter: "5. Ind AS on Assets of the Financial Statements", prompt: "General borrowings outstanding all year: ₹50 lakh at 10% and ₹30 lakh at 12%. Weighted average expenditure on a qualifying asset funded from general borrowings is ₹40 lakh. Borrowing cost to be capitalised is:", options: ["₹4,40,000", "₹4,00,000", "₹4,80,000", "₹4,30,000"], answer: 3, explanation: "Capitalisation rate = (5 + 3.6) / 80 = 10.75%, a weighted (not simple) average; 40 lakh × 10.75% = 4.3 lakh." },
    { id: "fr-025", chapter: "5. Ind AS on Assets of the Financial Statements", prompt: "A CGU has goodwill ₹20 lakh, PPE ₹60 lakh and other intangibles ₹40 lakh (no asset has a determinable recoverable amount on its own). Recoverable amount of the CGU is ₹90 lakh. After the impairment, PPE is carried at:", options: ["₹45 lakh", "₹50 lakh", "₹54 lakh", "₹60 lakh"], answer: 2, explanation: "Loss of 30 lakh: goodwill absorbs 20 first; the remaining 10 is shared pro rata 60:40, so PPE is reduced by 6 to 54 lakh." },
    { id: "fr-026", chapter: "5. Ind AS on Assets of the Financial Statements", prompt: "Which statement on impairment under Ind AS 36 is NOT correct?", options: ["Goodwill and indefinite-life intangibles are tested annually even without an indication", "An impairment loss on goodwill is reversed when the CGU's recoverable amount recovers", "Value in use excludes cash flows from a future restructuring the entity is not yet committed to", "Recoverable amount is the higher of fair value less costs of disposal and value in use"], answer: 1, explanation: "Ind AS 36 prohibits reversal of an impairment loss on goodwill; the other three statements are correct." },
    { id: "fr-027", chapter: "5. Ind AS on Assets of the Financial Statements", prompt: "A company spent ₹10 lakh on a development project from January to March, and the Ind AS 38 capitalisation criteria were first met on 1 April. It spent ₹15 lakh from April to December. Carrying amount of the intangible at 31 December is:", options: ["₹15 lakh", "₹25 lakh", "₹10 lakh", "Nil"], answer: 0, explanation: "Only expenditure after all criteria are met is capitalised; the 10 lakh already expensed cannot be reinstated as part of the asset's cost." },
    { id: "fr-028", chapter: "5. Ind AS on Assets of the Financial Statements", prompt: "Under Ind AS 40 as notified in India, investment property is measured after recognition:", options: ["using either the cost model or the fair value model as a policy choice", "using the cost model only, with fair value disclosed", "using the fair value model only, with changes in profit or loss", "using the revaluation model, with changes in OCI"], answer: 1, explanation: "Ind AS 40 removes the IAS 40 fair value model option: only the cost model is allowed, but fair value must be disclosed." },
    { id: "fr-029", chapter: "5. Ind AS on Assets of the Financial Statements", prompt: "A building is let to third parties except for one floor (20% of the area) used as the owner's head office. The floors cannot be sold or leased out separately under a finance lease. Under Ind AS 40, the building is:", options: ["accounted for wholly as investment property", "accounted for wholly as property, plant and equipment", "split 80% investment property and 20% PPE", "accounted for as inventory"], answer: 1, explanation: "If portions cannot be sold separately, the property is investment property only if an insignificant portion is owner-occupied; 20% is not insignificant." },
    { id: "fr-030", chapter: "5. Ind AS on Assets of the Financial Statements", prompt: "When classified as held for sale, an asset has a carrying amount of ₹50 lakh, fair value of ₹48 lakh and costs to sell of ₹3 lakh. Under Ind AS 105, the impairment loss recognised is:", options: ["₹2 lakh", "₹3 lakh", "₹5 lakh", "Nil"], answer: 2, explanation: "Measure at lower of carrying amount and fair value less costs to sell: 48 − 3 = 45, so the loss is 50 − 45 = 5 lakh; depreciation then stops." },
    { id: "fr-031", chapter: "5. Ind AS on Assets of the Financial Statements", prompt: "A lessee signs a 5-year lease of ₹10,00,000 per year payable in arrears; discount rate 10% (annuity factor 3.7908). It pays initial direct costs of ₹50,000 and receives a lease incentive of ₹1,00,000. The right-of-use asset at commencement is:", options: ["₹37,90,800", "₹38,40,800", "₹39,40,800", "₹37,40,800"], answer: 3, explanation: "Lease liability = 10,00,000 × 3.7908 = 37,90,800; ROU = liability + initial direct costs − incentive received = 37,40,800." },
    { id: "fr-032", chapter: "5. Ind AS on Assets of the Financial Statements", prompt: "A seller-lessee sells a building (carrying amount ₹40 lakh) for its fair value of ₹100 lakh, and the transfer is a sale under Ind AS 115. The present value of leaseback payments is ₹60 lakh. Gain recognised by the seller-lessee is:", options: ["₹60 lakh", "₹36 lakh", "Nil", "₹24 lakh"], answer: 3, explanation: "Only the gain on rights transferred is recognised: 60 × (100 − 60)/100 = 24 lakh; ROU asset = 40 × 60/100 = 24 lakh." },
    { id: "fr-033", chapter: "5. Ind AS on Assets of the Financial Statements", prompt: "Which of the following payments is NOT included in measuring a lessee's lease liability under Ind AS 116?", options: ["Variable payments based on 2% of the lessee's future sales from the premises", "Payments linked to the consumer price index, measured at the index at commencement", "Exercise price of a purchase option the lessee is reasonably certain to exercise", "Amounts expected to be payable under a residual value guarantee"], answer: 0, explanation: "Variable payments depending on an index or rate are included; those linked to future performance or usage (such as sales) are expensed when incurred." },
    { id: "fr-034", chapter: "6. Ind AS on Liabilities of the Financial Statements", prompt: "A non-cancellable contract will earn ₹10 lakh; fulfilling it will cost ₹13 lakh. The entity can exit by paying a penalty of ₹2.5 lakh. Under Ind AS 37, the onerous contract provision is:", options: ["₹2.5 lakh", "₹3 lakh", "₹13 lakh", "Nil"], answer: 0, explanation: "Unavoidable cost is the lower of the net cost of fulfilling (13 − 10 = 3 lakh) and the exit penalty (2.5 lakh)." },
    { id: "fr-035", chapter: "6. Ind AS on Liabilities of the Financial Statements", prompt: "A board-approved restructuring has been announced to those affected. Estimated costs: redundancy pay ₹10 lakh, retraining of continuing staff ₹3 lakh, relocation of continuing staff ₹2 lakh, penalty for cancelling a supply contract of the closed division ₹1 lakh. The provision is:", options: ["₹16 lakh", "₹13 lakh", "₹11 lakh", "₹10 lakh"], answer: 2, explanation: "Only direct costs not associated with ongoing activities qualify: redundancy 10 + contract penalty 1 = 11 lakh; retraining and relocation relate to the future business." },
    { id: "fr-036", chapter: "6. Ind AS on Liabilities of the Financial Statements", prompt: "A company sells 1,000 units with a one-year warranty. Expected outcomes: 80% no defects, 15% minor defects (₹2,000 each), 5% major defects (₹10,000 each). The warranty provision is:", options: ["₹3,00,000", "₹5,00,000", "₹12,00,000", "₹8,00,000"], answer: 3, explanation: "For a large population use the expected value: 1,000 × (15% × 2,000 + 5% × 10,000) = 1,000 × 800 = 8 lakh." },
    { id: "fr-037", chapter: "6. Ind AS on Liabilities of the Financial Statements", prompt: "A company has a provision of ₹20 lakh for a damages claim; its insurer will reimburse ₹15 lakh, which is virtually certain. Under Ind AS 37:", options: ["the provision is shown net of the reimbursement at ₹5 lakh", "the reimbursement is only disclosed as a contingent asset", "the reimbursement is recognised only when the cash is received", "a separate ₹15 lakh asset is recognised; the liability stays ₹20 lakh"], answer: 3, explanation: "A virtually certain reimbursement is a separate asset (capped at the provision) and cannot be netted against the liability in the balance sheet." },
    { id: "fr-038", chapter: "6. Ind AS on Liabilities of the Financial Statements", prompt: "Defined benefit plan: opening obligation ₹100 lakh, plan assets ₹80 lakh, discount rate 8%, current service cost ₹10 lakh. Closing remeasurements are a net loss of ₹0.4 lakh. The amount charged to profit or loss for the year is:", options: ["₹18 lakh", "₹12 lakh", "₹11.6 lakh", "₹10 lakh"], answer: 2, explanation: "Profit or loss = service cost 10 + net interest 8% × (100 − 80) = 1.6, total 11.6 lakh; remeasurements go to OCI." },
    { id: "fr-039", chapter: "6. Ind AS on Liabilities of the Financial Statements", prompt: "Under Ind AS 19 as applicable in India, an Indian company discounts its post-employment benefit obligations by reference to market yields at the reporting date on:", options: ["high quality corporate bonds, with government bonds only if there is no deep market", "the company's own borrowing rate", "the expected return on plan assets", "government bonds"], answer: 3, explanation: "Ind AS 19 departs from IAS 19 by requiring government bond yields; overseas subsidiaries etc. may use high quality corporate bonds where a deep market exists." },
    { id: "fr-040", chapter: "7. Ind AS on Items impacting the Financial Statements", prompt: "Plant has a carrying amount of ₹80 lakh and a tax base of ₹60 lakh; the enacted tax rate is 25%. The deferred tax position is:", options: ["Deferred tax asset ₹5 lakh", "Deferred tax liability ₹20 lakh", "Deferred tax liability ₹5 lakh", "Deferred tax liability ₹15 lakh"], answer: 2, explanation: "Carrying amount above tax base is a taxable temporary difference of 20 lakh; 20 × 25% = 5 lakh DTL." },
    { id: "fr-041", chapter: "7. Ind AS on Items impacting the Financial Statements", prompt: "A company has unused tax losses of ₹40 lakh. Taxable temporary differences of ₹10 lakh will reverse in the period the losses can be used, and further taxable profits of ₹12 lakh are probable. Tax rate 25%. The deferred tax asset recognised on the losses is:", options: ["₹10 lakh", "₹2.5 lakh", "₹3 lakh", "₹5.5 lakh"], answer: 3, explanation: "Recognise the DTA only to the extent of probable taxable profits: (10 + 12) × 25% = 5.5 lakh; the rest is unrecognised." },
    { id: "fr-042", chapter: "7. Ind AS on Items impacting the Financial Statements", prompt: "A new tax rate is announced and substantively enacted two weeks AFTER the reporting date. For deferred tax at the reporting date, the entity:", options: ["uses the old rate and discloses the effect of the change if material", "uses the new rate because it is known before the financial statements are approved", "uses the average of the two rates", "remeasures deferred tax at the new rate through OCI"], answer: 0, explanation: "Ind AS 12 uses rates enacted or substantively enacted by the end of the reporting period; a later change is a non-adjusting event." },
    { id: "fr-043", chapter: "7. Ind AS on Items impacting the Financial Statements", prompt: "A parent has undistributed profits in a subsidiary (a taxable temporary difference). Under Ind AS 12, no deferred tax liability is recognised if:", options: ["the parent controls the timing of reversal and reversal is not probable in the foreseeable future", "the subsidiary is located outside India and its profits are taxed there", "the subsidiary has a long-standing policy of paying a dividend every year", "the amount is immaterial to the subsidiary's own financial statements"], answer: 0, explanation: "Both conditions (control over timing and no reversal in the foreseeable future) are needed; a parent normally controls a subsidiary's dividend policy." },
    { id: "fr-044", chapter: "7. Ind AS on Items impacting the Financial Statements", prompt: "Goods invoiced at USD 10,000 are bought on credit on 1 February (₹82/USD). At 31 March (year end) the rate is ₹84; payment is made on 30 April at ₹83. The goods are unsold at year end. Under Ind AS 21, at 31 March:", options: ["Inventory ₹8,40,000; no exchange loss", "Inventory ₹8,30,000; exchange loss ₹10,000", "Inventory ₹8,20,000; exchange loss ₹20,000", "Inventory ₹8,20,000; no exchange difference until payment"], answer: 2, explanation: "Inventory is non-monetary and stays at the historical rate; the payable is monetary and is retranslated at 84, giving a loss of 10,000 × 2 = 20,000." },
    { id: "fr-045", chapter: "7. Ind AS on Items impacting the Financial Statements", prompt: "A company pays a non-refundable advance of USD 5,000 on 1 January (₹80/USD) for machinery received on 1 March (₹82/USD), when no further payment is due. The machinery is initially recognised at:", options: ["₹4,00,000", "₹4,10,000", "₹4,05,000", "₹4,10,000, with an exchange loss of ₹10,000 in profit or loss"], answer: 0, explanation: "The date of transaction is when the non-monetary prepayment asset was first recognised (1 January), so the rate of 80 applies: 5,000 × 80 = 4 lakh." },
    { id: "fr-046", chapter: "7. Ind AS on Items impacting the Financial Statements", prompt: "A foreign subsidiary's opening net assets are FC 1,000 (opening rate ₹70). Profit for the year is FC 200 (average rate ₹72 is a fair approximation). Closing rate is ₹75 and there were no other movements. The exchange difference taken to OCI for the year is:", options: ["₹5,000", "₹6,000", "₹600", "₹5,600"], answer: 3, explanation: "Closing net assets 1,200 × 75 = 90,000 less (1,000 × 70 + 200 × 72 = 84,400) = 5,600, recognised in OCI." },
    { id: "fr-047", chapter: "7. Ind AS on Items impacting the Financial Statements", prompt: "Which of the following is NOT one of the primary indicators of an entity's functional currency under Ind AS 21?", options: ["The currency that mainly influences sales prices for its goods and services", "The currency of the country whose competitive forces and regulations mainly determine its sales prices", "The currency that mainly influences labour, material and other costs", "The currency in which funds from financing activities are generated"], answer: 3, explanation: "Currency of financing and of retained operating receipts are secondary indicators; the primary ones relate to sales prices and costs." },
    { id: "fr-048", chapter: "8. Ind AS on Disclosures in the Financial Statements", prompt: "Profit for the year (April-March) is ₹60 lakh. 10 lakh shares were outstanding throughout, and a 1:4 bonus issue was made on 1 January. Basic EPS is:", options: ["₹5.65", "₹4.80", "₹6.00", "₹5.00"], answer: 1, explanation: "Bonus shares are treated as outstanding from the start of the period: 12.5 lakh shares; 60 / 12.5 = ₹4.80 (time-weighting them gives 5.65, which is wrong)." },
    { id: "fr-049", chapter: "8. Ind AS on Disclosures in the Financial Statements", prompt: "Last year's reported basic EPS was ₹7.50. This year a 1:4 rights issue was made at ₹40 when the fair value before the rights was ₹60 per share. The restated EPS for the previous year is:", options: ["₹7.00", "₹7.50", "₹8.04", "₹6.00"], answer: 0, explanation: "TERP = (4 × 60 + 1 × 40)/5 = 56; restated EPS = 7.50 × 56/60 = ₹7.00 (adjusting for the bonus element)." },
    { id: "fr-050", chapter: "8. Ind AS on Disclosures in the Financial Statements", prompt: "Profit ₹100 lakh; shares 50 lakh. Potential shares: (i) options giving 4 lakh free shares (no profit effect); (ii) debentures A: post-tax interest saved ₹12 lakh, 10 lakh shares; (iii) debentures B: post-tax interest saved ₹30 lakh, 10 lakh shares. Diluted EPS is:", options: ["₹1.92", "₹1.75", "₹1.85", "₹1.87"], answer: 1, explanation: "Order most dilutive first: options 100/54 = 1.85, then A 112/64 = 1.75; adding B gives 142/74 = 1.92, which is antidilutive, so it is excluded." },
    { id: "fr-051", chapter: "8. Ind AS on Disclosures in the Financial Statements", prompt: "Investor Z has two associates, P and Q, and no other relationships exist. Under Ind AS 24, which statement is correct?", options: ["P and Q are not related parties of each other, but each is a related party of Z", "P and Q are related parties of each other because they share a common investor", "P is a related party of Z, but Z is not a related party of P", "Neither P nor Q is a related party of Z, because Z lacks control"], answer: 0, explanation: "Two associates of the same investor are not related to each other; an investor and its associate are related. (A JV and an associate of the same entity would be related.)" },
    { id: "fr-052", chapter: "8. Ind AS on Disclosures in the Financial Statements", prompt: "Under Ind AS 24, which of the following is included in 'close members of the family' of a KMP, a departure from IAS 24?", options: ["The KMP's cousins", "The KMP's spouse's parents only", "Any relative who holds shares in the entity", "The KMP's brother, sister, father and mother"], answer: 3, explanation: "Ind AS 24 expressly includes brother, sister, father and mother in addition to children, spouse or domestic partner and dependants." },
    { id: "fr-053", chapter: "8. Ind AS on Disclosures in the Financial Statements", prompt: "Operating segments report the following results (₹ lakh): A +500, B +200, C −400, D −60, E +40. Under the profit or loss threshold of Ind AS 108, which segments are reportable?", options: ["A and B only", "A, B and C", "A, B, C and D", "All five segments"], answer: 1, explanation: "Threshold = 10% of the greater of combined profits (740) and combined losses (460) = 74; A, B and C (by absolute amount) exceed it." },
    { id: "fr-054", chapter: "8. Ind AS on Disclosures in the Financial Statements", prompt: "Reportable segments identified under the quantitative thresholds account for 70% of the entity's external revenue. Under Ind AS 108, the entity must:", options: ["aggregate all remaining segments into a single reportable segment", "identify additional operating segments as reportable until at least 75% of external revenue is covered", "report only the identified segments and disclose the shortfall", "lower the 10% thresholds proportionately"], answer: 1, explanation: "If external revenue of reportable segments is below 75% of entity revenue, more segments are reported (even below 10%) until 75% is reached." },
    { id: "fr-055", chapter: "9. Ind AS 115 \"Revenue from Contracts with Customers\"", prompt: "A sells products X (SSP ₹60,000), Y (SSP ₹30,000) and Z (SSP ₹30,000) together for ₹1,00,000. A regularly sells each separately at SSP and regularly sells Y and Z together for ₹40,000. Transaction price allocated to X is:", options: ["₹50,000", "₹40,000", "₹53,333", "₹60,000"], answer: 3, explanation: "Observable evidence shows the whole ₹20,000 discount relates to Y and Z, so it is allocated only to them; X gets its SSP of ₹60,000." },
    { id: "fr-056", chapter: "9. Ind AS 115 \"Revenue from Contracts with Customers\"", prompt: "Price is ₹100 per unit, but if a customer buys over 1,000 units in the year the price becomes ₹90 for ALL units. In Q1 the customer buys 200 units, and the entity expects (highly probably) annual purchases of 1,200 units. Q1 revenue is:", options: ["₹20,000", "₹18,000", "₹19,000", "Nil"], answer: 1, explanation: "Variable consideration is estimated at ₹90 per unit as the threshold is highly probable to be met: 200 × 90 = 18,000; ₹2,000 is a refund liability." },
    { id: "fr-057", chapter: "9. Ind AS 115 \"Revenue from Contracts with Customers\"", prompt: "100 units are sold at ₹500 each (cost ₹300) with a right of return; 5% are expected to be returned. Revenue recognised on sale is:", options: ["₹50,000", "₹28,500", "₹47,500", "₹45,000"], answer: 2, explanation: "Revenue excludes expected returns: 95 × 500 = 47,500, with a refund liability of 2,500 and an asset of 1,500 for goods to be recovered." },
    { id: "fr-058", chapter: "9. Ind AS 115 \"Revenue from Contracts with Customers\"", prompt: "Which of the following is NOT an indicator in Ind AS 115 that an entity controls a specified good before it is transferred (i.e. is a principal)?", options: ["The entity is primarily responsible for fulfilling the promise", "The entity has inventory risk before or after transfer of control", "The entity has discretion in establishing the price", "The entity bears the customer's credit risk"], answer: 3, explanation: "Ind AS 115 lists three indicators: primary responsibility, inventory risk and pricing discretion; credit risk is not an indicator." },
    { id: "fr-059", chapter: "9. Ind AS 115 \"Revenue from Contracts with Customers\"", prompt: "A customer pays ₹10,00,000 two years before delivery, or could pay ₹12,10,000 on delivery; the financing component is significant and the rate is 10%. Revenue recognised on delivery is:", options: ["₹10,00,000", "₹12,10,000", "₹11,00,000", "₹12,00,000"], answer: 1, explanation: "Interest expense accrues on the contract liability (1,00,000 + 1,10,000), so it grows to 12,10,000, which is recognised as revenue on delivery." },
    { id: "fr-060", chapter: "9. Ind AS 115 \"Revenue from Contracts with Customers\"", prompt: "A contract to deliver 100 units at ₹1,000 each is modified after 60 are delivered to add 30 distinct units at ₹800 (SSP ₹1,000; the discount is not for a customer-specific reason). Revenue per unit for the remaining units is:", options: ["₹1,000.00", "₹800.00", "₹914.29", "₹925.00"], answer: 2, explanation: "Price below SSP and goods distinct: treat as termination plus new contract. (40 × 1,000 + 30 × 800) / 70 = 64,000 / 70 = 914.29." },
    { id: "fr-061", chapter: "9. Ind AS 115 \"Revenue from Contracts with Customers\"", prompt: "A company makes highly customised equipment with no alternative use. If the customer terminates, the contract entitles the company only to reimbursement of costs incurred to date, with no margin. Under Ind AS 115, revenue is recognised:", options: ["over time, because the equipment has no alternative use to the company", "at a point in time, because the right to payment for work done has no margin", "over time, because the customer controls the equipment as it is built", "over time, because costs incurred to date are recoverable from the customer"], answer: 1, explanation: "Over time under the third criterion needs both no alternative use and a right to payment covering cost plus a reasonable margin; cost-only recovery fails." },
    { id: "fr-062", chapter: "9. Ind AS 115 \"Revenue from Contracts with Customers\"", prompt: "Contract price ₹80 lakh; total expected costs ₹60 lakh, including specialised chillers bought from a third party for ₹20 lakh. Costs to date are ₹30 lakh, including the chillers (delivered to site, control passed, not yet installed). Using cost-to-cost, revenue to date is:", options: ["₹35 lakh", "₹40 lakh", "₹20 lakh", "₹30 lakh"], answer: 0, explanation: "Uninstalled materials are excluded from progress and recognised at cost: progress = 10/40 = 25%; revenue = 25% × (80 − 20) + 20 = 35 lakh." },
    { id: "fr-063", chapter: "9. Ind AS 115 \"Revenue from Contracts with Customers\"", prompt: "A retailer sells goods for ₹1,00,000 and grants 10,000 loyalty points worth ₹1 each; 90% are expected to be redeemed. Standalone selling price of the goods is ₹1,00,000. Revenue deferred for the points at the point of sale is:", options: ["₹9,000", "₹10,000", "₹8,257", "₹8,182"], answer: 2, explanation: "SSP of points = 10,000 × 1 × 90% = 9,000; allocation = 1,00,000 × 9,000 / 1,09,000 = 8,257." },
    { id: "fr-064", chapter: "9. Ind AS 115 \"Revenue from Contracts with Customers\"", prompt: "To obtain a contract, a company pays a sales commission of ₹50,000 (payable only if the contract is won), external legal fees for due diligence of ₹20,000 and travel costs of ₹10,000. The contract term is 3 years. The asset recognised for costs of obtaining the contract is:", options: ["₹80,000", "₹70,000", "₹50,000", "Nil"], answer: 2, explanation: "Only incremental costs (incurred solely because the contract was obtained) are capitalised; legal and travel costs would be incurred anyway and are expensed." },
    { id: "fr-065", chapter: "10. Other Indian Accounting Standards", prompt: "A government lends ₹10,00,000 interest-free, repayable in a lump sum after 3 years; the market rate is 10% (1.1^3 = 1.331). Under Ind AS 20 read with Ind AS 109, the government grant is:", options: ["₹10,00,000", "₹3,00,000", "₹7,51,315", "₹2,48,685"], answer: 3, explanation: "Loan is recognised at fair value 10,00,000 / 1.331 = 7,51,315; the benefit of below-market interest (10,00,000 − 7,51,315 = 2,48,685) is a grant." },
    { id: "fr-066", chapter: "10. Other Indian Accounting Standards", prompt: "A grant related to income has an unamortised deferred credit of ₹3 lakh when ₹5 lakh becomes repayable. Under Ind AS 20, the repayment is accounted for by:", options: ["setting ₹3 lakh against the deferred credit and expensing ₹2 lakh", "recognising the full ₹5 lakh as an expense in profit or loss", "restating prior periods as the correction of an error", "debiting the full ₹5 lakh directly to retained earnings"], answer: 0, explanation: "Repayment of a grant is a change in estimate: set it off against any unamortised deferred credit, with the excess expensed immediately." },
    { id: "fr-067", chapter: "10. Other Indian Accounting Standards", prompt: "Which of the following is within the scope of Ind AS 41 Agriculture?", options: ["Tea bushes that are bearer plants", "Tea leaves processed into packaged tea", "Land on which crops are grown", "Dairy cattle held for milk production"], answer: 3, explanation: "Bearer plants are under Ind AS 16, processed products under Ind AS 2 and land under Ind AS 16/40; animals, including dairy cattle, stay in Ind AS 41." },
    { id: "fr-068", chapter: "10. Other Indian Accounting Standards", prompt: "100 employees each get 100 options (grant-date fair value ₹30), vesting after 3 years of service. At end of year 1, 90% are expected to vest; at end of year 2, 85%. Expense for year 2 is:", options: ["₹80,000", "₹85,000", "₹1,70,000", "₹90,000"], answer: 0, explanation: "Cumulative to Y2 = 3,00,000 × 85% × 2/3 = 1,70,000 less Y1 expense (3,00,000 × 90% × 1/3 = 90,000) = 80,000." },
    { id: "fr-069", chapter: "10. Other Indian Accounting Standards", prompt: "Options vest only if employees serve 3 years AND the share price reaches ₹500. All employees serve the 3 years but the price target is not met. Under Ind AS 102 the expense already recognised is:", options: ["reversed in full, because the options did not vest", "reversed and transferred to OCI", "reversed only to the extent of the share price shortfall", "retained, because the market condition was reflected in grant-date fair value"], answer: 3, explanation: "Market conditions are built into grant-date fair value; if the service condition is met, expense is not reversed even though the market condition fails." },
    { id: "fr-070", chapter: "11. Accounting and Reporting of Financial Instruments", prompt: "A debt investment meets the SPPI test and is held in a business model whose objective is achieved both by collecting contractual cash flows and by selling. Under Ind AS 109, it is measured at:", options: ["amortised cost", "FVOCI, with gains never recycled", "FVOCI, with cumulative gains recycled to profit or loss on derecognition", "cost less impairment"], answer: 2, explanation: "Hold-to-collect-and-sell plus SPPI gives FVOCI for debt; unlike FVOCI equity, cumulative gains or losses are recycled on derecognition." },
    { id: "fr-071", chapter: "11. Accounting and Reporting of Financial Instruments", prompt: "A company makes the irrevocable election to present fair value changes of a strategic equity investment in OCI. Which statement is correct?", options: ["Fair value gains are recycled to profit or loss on sale", "Dividends go to profit or loss; fair value gains are never recycled, even on sale", "Impairment losses are recognised in profit or loss", "The election can be made for equity instruments held for trading"], answer: 1, explanation: "For FVOCI equity, there is no impairment and no recycling; dividends are in profit or loss. The election is not available for held-for-trading equity." },
    { id: "fr-072", chapter: "11. Accounting and Reporting of Financial Instruments", prompt: "A bond with face value ₹10,00,000 and coupon 8% (paid annually) is bought for ₹9,50,000 and measured at amortised cost; the effective interest rate is 9.5%. Amortised cost at the end of year 1 is:", options: ["₹9,60,250", "₹9,50,000", "₹9,70,000", "₹10,10,250"], answer: 0, explanation: "Interest income = 9,50,000 × 9.5% = 90,250; amortised cost = 9,50,000 + 90,250 − 80,000 coupon = 9,60,250." },
    { id: "fr-073", chapter: "11. Accounting and Reporting of Financial Instruments", prompt: "Shares held for trading are bought for ₹5,00,000 plus brokerage of ₹5,000. At initial recognition under Ind AS 109:", options: ["the asset is ₹5,05,000", "the asset is ₹4,95,000", "the asset is ₹5,00,000 and brokerage of ₹5,000 is expensed", "the asset is ₹5,00,000 and brokerage is debited to OCI"], answer: 2, explanation: "Transaction costs are added only for assets not at FVTPL; for FVTPL assets they are expensed immediately." },
    { id: "fr-074", chapter: "11. Accounting and Reporting of Financial Instruments", prompt: "Receivables (no significant financing component): not due ₹10 lakh (1% loss rate), 1-30 days ₹5 lakh (3%), 31-90 days ₹4 lakh (10%), over 90 days ₹1 lakh (50%). Loss allowance under a provision matrix is:", options: ["₹1,00,000", "₹1,25,000", "₹1,15,000", "₹65,000"], answer: 2, explanation: "10,000 + 15,000 + 40,000 + 50,000 = 1,15,000." },
    { id: "fr-075", chapter: "11. Accounting and Reporting of Financial Instruments", prompt: "Under the general ECL model, interest revenue is calculated on the amortised cost (net of loss allowance) rather than the gross carrying amount for:", options: ["Stage 3 (credit-impaired) assets only", "Stage 2 and Stage 3 assets", "Stage 1 assets only", "All stages once a loss allowance exists"], answer: 0, explanation: "Stages 1 and 2 earn interest on the gross carrying amount; only credit-impaired (Stage 3) assets use the net amortised cost." },
    { id: "fr-076", chapter: "11. Accounting and Reporting of Financial Instruments", prompt: "Convertible debentures of ₹10,00,000 carry 6% interest for 3 years; similar non-convertible debt yields 10% (PV factors 0.909, 0.826, 0.751). The equity component on initial recognition is:", options: ["₹9,00,160", "₹1,49,160", "Nil", "₹99,840"], answer: 3, explanation: "Liability = 60,000 × 2.486 + 10,00,000 × 0.751 = 1,49,160 + 7,51,000 = 9,00,160; equity = 10,00,000 − 9,00,160 = 99,840." },
    { id: "fr-077", chapter: "11. Accounting and Reporting of Financial Instruments", prompt: "An entity must settle an obligation by delivering as many of its own shares as are worth exactly ₹50 lakh on the settlement date. Under Ind AS 32, this is:", options: ["equity, since it is settled in own shares", "a financial liability, since the number of shares varies", "a compound instrument", "equity only if the shares are listed"], answer: 1, explanation: "It fails the fixed-for-fixed test: the holder gets a fixed value, not a residual interest, so it is a financial liability." },
    { id: "fr-078", chapter: "11. Accounting and Reporting of Financial Instruments", prompt: "A company factors trade receivables with full recourse for credit losses and retains substantially all risks and rewards. Under Ind AS 109, the company:", options: ["keeps the receivables and records the cash received as a financial liability", "derecognises the receivables and recognises a gain or loss on transfer", "derecognises the receivables and discloses the recourse as a contingency", "recognises the receivables only to the extent of its continuing involvement"], answer: 0, explanation: "Retaining substantially all risks and rewards prevents derecognition; the proceeds are a collateralised borrowing." },
    { id: "fr-079", chapter: "11. Accounting and Reporting of Financial Instruments", prompt: "Which statement on reclassification under Ind AS 109 is NOT correct?", options: ["Financial assets are reclassified only when the business model for managing them changes", "Financial liabilities are reclassified when the entity's intention changes", "Reclassification of financial assets is applied prospectively from the reclassification date", "Investments in equity instruments designated at FVOCI cannot be reclassified"], answer: 1, explanation: "Financial liabilities are never reclassified under Ind AS 109; the other statements are correct." },
    { id: "fr-080", chapter: "11. Accounting and Reporting of Financial Instruments", prompt: "A parent guarantees its subsidiary's bank loan free of charge. In the parent's separate financial statements, the fair value of the guarantee at inception is recognised as:", options: ["a financial liability, with a corresponding increase in its investment in the subsidiary", "a financial liability, with an immediate expense in profit or loss", "a contingent liability disclosed only in the notes", "income, as the guarantee benefits the group"], answer: 0, explanation: "The guarantee is a financial liability at fair value; giving it free to a subsidiary is a capital contribution, added to the cost of investment." },
    { id: "fr-081", chapter: "11. Accounting and Reporting of Financial Instruments", prompt: "For a financial liability designated at FVTPL, the change in fair value due to changes in the entity's own credit risk is generally presented:", options: ["in profit or loss with the rest of the fair value change", "in OCI, recycled to profit or loss on derecognition", "in OCI, without later reclassification to profit or loss", "directly in retained earnings"], answer: 2, explanation: "Ind AS 109 puts own-credit changes in OCI (unless that creates an accounting mismatch) and prohibits recycling." },
    { id: "fr-082", chapter: "12. Ind AS 103 \"Business Combinations\"", prompt: "P acquires 70% of S for ₹80 lakh. Fair value of S's identifiable net assets is ₹90 lakh and the fair value of NCI is ₹30 lakh. Goodwill if NCI is measured at its proportionate share of net assets is:", options: ["₹20 lakh", "₹27 lakh", "₹17 lakh", "₹10 lakh"], answer: 2, explanation: "Goodwill = 80 + (30% × 90 = 27) − 90 = 17 lakh; the 20 lakh figure uses NCI at fair value (full goodwill)." },
    { id: "fr-083", chapter: "12. Ind AS 103 \"Business Combinations\"", prompt: "After reassessing all assets, liabilities and the consideration, an acquirer still finds a bargain purchase, and there is clear evidence of the reasons for it. Under Ind AS 103, the gain is:", options: ["recognised in OCI and accumulated in equity as capital reserve", "recognised in profit or loss on the acquisition date", "deducted from the cost of the investment", "deferred and amortised over five years"], answer: 0, explanation: "Ind AS 103 departs from IFRS 3: the gain goes to OCI and capital reserve (or directly to capital reserve if there is no clear evidence)." },
    { id: "fr-084", chapter: "12. Ind AS 103 \"Business Combinations\"", prompt: "Contingent consideration classified as a financial liability is remeasured six months after acquisition because the acquiree's profits beat targets (a post-acquisition event). The increase in fair value is:", options: ["recognised in profit or loss", "added to goodwill as a measurement period adjustment", "recognised in equity", "not recognised until settlement"], answer: 0, explanation: "Only adjustments for facts existing at the acquisition date adjust goodwill; changes due to post-acquisition events go to profit or loss." },
    { id: "fr-085", chapter: "12. Ind AS 103 \"Business Combinations\"", prompt: "Eight months after an acquisition, a valuation shows that PPE provisionally recorded at ₹50 lakh was worth ₹45 lakh at the acquisition date. Ignoring tax, the acquirer:", options: ["recognises a ₹5 lakh impairment loss in the current period", "adjusts nothing, as the measurement period is six months", "increases goodwill by ₹5 lakh retrospectively and restates comparatives", "reduces equity by ₹5 lakh"], answer: 2, explanation: "Within the measurement period (up to one year), new information on facts at acquisition date adjusts provisional amounts and goodwill retrospectively." },
    { id: "fr-086", chapter: "12. Ind AS 103 \"Business Combinations\"", prompt: "An acquirer pays ₹1 crore for a business, incurs legal and due diligence fees of ₹5 lakh, and ₹2 lakh to register the shares it issued as consideration. Under Ind AS 103:", options: ["₹7 lakh is added to the consideration in computing goodwill", "₹5 lakh is added to goodwill and ₹2 lakh is expensed", "₹7 lakh is expensed", "₹5 lakh is expensed and ₹2 lakh is deducted from equity"], answer: 3, explanation: "Acquisition-related costs are expensed; costs to issue equity are accounted for under Ind AS 32 as a deduction from equity." },
    { id: "fr-087", chapter: "12. Ind AS 103 \"Business Combinations\"", prompt: "P holds 20% of S (equity-accounted, carrying amount ₹15 lakh) and buys a further 40% for ₹48 lakh, gaining control. The fair value of the 20% at that date is ₹24 lakh; S's identifiable net assets are ₹100 lakh; NCI is measured at its proportionate share. Goodwill is:", options: ["₹12 lakh", "₹3 lakh", "₹8 lakh", "₹20 lakh"], answer: 0, explanation: "The previously held interest is remeasured to fair value (gain 9 lakh): goodwill = 48 + 24 + 40 − 100 = 12 lakh." },
    { id: "fr-088", chapter: "12. Ind AS 103 \"Business Combinations\"", prompt: "Two companies controlled by the same parent before and after the transaction (not transitory) are amalgamated. Under Appendix C of Ind AS 103:", options: ["the acquisition method applies, with goodwill recognised", "the pooling of interests method applies, with assets and liabilities at carrying amounts", "assets are restated to fair value but no goodwill arises", "the transferee chooses either the acquisition or pooling method"], answer: 1, explanation: "Common control combinations use pooling of interests: carrying amounts, no new goodwill; any difference goes to capital reserve." },
    { id: "fr-089", chapter: "12. Ind AS 103 \"Business Combinations\"", prompt: "A company buys a set of activities and assets where substantially all the fair value of gross assets acquired is in a single building. Applying the optional concentration test in Ind AS 103, the purchase is:", options: ["a business combination, with goodwill recognised", "an asset acquisition, not a business combination", "a business combination, with a bargain purchase gain", "a common control transaction"], answer: 1, explanation: "If the concentration test is met, the set is not a business; the cost is allocated to the assets acquired and no goodwill arises." },
    { id: "fr-090", chapter: "13. Consolidated and Separate Financial Statements of Group Entities", prompt: "Under Ind AS 110, which of the following is the most likely to give an investor control without a majority of voting rights?", options: ["45% of votes, where two other investors hold 30% and 25% and always vote together", "45% of votes plus options exercisable only in five years at a price far above market", "45% of votes, with the other 55% spread over thousands of holders of under 1% each", "45% of votes plus protective rights over major capital expenditure decisions"], answer: 2, explanation: "A large holding relative to a widely dispersed remainder can give de facto power; out-of-the-money long-dated options and protective rights do not." },
    { id: "fr-091", chapter: "13. Consolidated and Separate Financial Statements of Group Entities", prompt: "Under Ind AS 110, losses of a subsidiary attributable to NCI are:", options: ["attributed to NCI only up to the NCI balance, with the excess borne by the parent", "borne entirely by the parent", "attributed to NCI only if NCI has a binding obligation to fund losses", "attributed to NCI even if this results in a deficit (debit) balance on NCI"], answer: 3, explanation: "Total comprehensive income is attributed to owners and NCI even if NCI becomes negative." },
    { id: "fr-092", chapter: "13. Consolidated and Separate Financial Statements of Group Entities", prompt: "A parent owns 80% of a subsidiary with net assets of ₹200 lakh (NCI ₹40 lakh, proportionate basis, no goodwill). It sells a 10% stake for ₹30 lakh and keeps control. The consolidated accounting is:", options: ["NCI rises by ₹20 lakh and ₹10 lakh is credited to the parent's equity", "NCI rises by ₹20 lakh and a ₹10 lakh gain goes to profit or loss", "NCI rises by ₹30 lakh, with no gain recognised anywhere", "NCI rises by ₹20 lakh and a ₹10 lakh gain is recognised in OCI"], answer: 0, explanation: "Changes in ownership without loss of control are equity transactions: NCI rises by 10% × 200 = 20 lakh; the excess 10 lakh goes to parent's equity." },
    { id: "fr-093", chapter: "13. Consolidated and Separate Financial Statements of Group Entities", prompt: "A parent holds 80% of S (net assets ₹100 lakh, goodwill ₹20 lakh, NCI ₹20 lakh). It sells 60% of S for ₹90 lakh, losing control; the retained 20% has a fair value of ₹30 lakh. No OCI items exist. Gain on loss of control in consolidated profit or loss is:", options: ["Nil", "₹10 lakh", "₹30 lakh", "₹20 lakh"], answer: 3, explanation: "Gain = (90 + 30 + NCI 20) − (net assets 100 + goodwill 20) = 20 lakh; the retained interest is remeasured to fair value." },
    { id: "fr-094", chapter: "13. Consolidated and Separate Financial Statements of Group Entities", prompt: "An 80%-owned subsidiary sells goods costing ₹1,00,000 to its parent for ₹1,20,000; half remain in the parent's inventory at year end. In consolidation, the unrealised profit elimination reduces NCI by:", options: ["Nil", "₹10,000", "₹2,000", "₹4,000"], answer: 2, explanation: "Upstream sale: unrealised profit 10,000 is fully eliminated and shared with NCI: 20% × 10,000 = 2,000." },
    { id: "fr-095", chapter: "13. Consolidated and Separate Financial Statements of Group Entities", prompt: "An investor's equity-accounted interest in an associate has a carrying amount of ₹10 lakh; it also holds an unsecured long-term loan to the associate of ₹3 lakh, with settlement neither planned nor likely. Its share of the associate's loss for the year is ₹14 lakh. The loss recognised is:", options: ["₹13 lakh", "₹10 lakh", "₹14 lakh", "₹3 lakh"], answer: 0, explanation: "Losses reduce the equity interest to nil and then long-term interests forming part of the net investment: 10 + 3 = 13 lakh; 1 lakh stays unrecognised." },
    { id: "fr-096", chapter: "13. Consolidated and Separate Financial Statements of Group Entities", prompt: "An investor with 30% of an associate sells it goods at a profit of ₹50,000; all the goods remain in the associate's inventory at year end. Under Ind AS 28, the unrealised profit eliminated is:", options: ["₹15,000", "₹50,000", "₹35,000", "Nil"], answer: 0, explanation: "Gains on downstream transactions with an associate are eliminated only to the extent of the investor's interest: 30% × 50,000 = 15,000." },
    { id: "fr-097", chapter: "13. Consolidated and Separate Financial Statements of Group Entities", prompt: "Two parties have joint control over an arrangement run through a separate company. The legal form and contractual terms give the parties rights only to the net assets of the company. Under Ind AS 111, the arrangement is:", options: ["a joint operation, with each party recognising its share of assets and liabilities", "a subsidiary of both parties, consolidated by each", "a joint venture, accounted for using the equity method", "a financial asset at FVTPL"], answer: 2, explanation: "Rights to the net assets make it a joint venture; rights to assets and obligations for liabilities would make it a joint operation." },
    { id: "fr-098", chapter: "14. Ind AS 101 \"First-time Adoption of Ind AS\"", prompt: "A company's first Ind AS financial statements are for the year ending 31 March 2028, with one year of comparatives. Its date of transition to Ind AS is:", options: ["1 April 2026", "1 April 2027", "31 March 2027", "31 March 2028"], answer: 0, explanation: "Transition date is the beginning of the earliest period with full comparative information: 1 April 2026, when the opening Ind AS balance sheet is prepared." },
    { id: "fr-099", chapter: "14. Ind AS 101 \"First-time Adoption of Ind AS\"", prompt: "Under Ind AS 101, which statement about estimates at the date of transition is correct?", options: ["They are revised using information received after the transition date", "They must all be made afresh, at fair value, as at the transition date", "Ind AS 101 allows a choice between previous GAAP estimates and hindsight", "They follow previous GAAP estimates (after policy adjustments) unless in error"], answer: 3, explanation: "This is a mandatory exception: hindsight is not allowed; later information is reflected as for a non-adjusting event." },
    { id: "fr-100", chapter: "14. Ind AS 101 \"First-time Adoption of Ind AS\"", prompt: "Which of the following exemptions in Ind AS 101 is specific to India (not in IFRS 1)?", options: ["Previous GAAP carrying amounts as deemed cost for all PPE and intangibles", "Fair value at the transition date as deemed cost for an item of PPE", "Not restating business combinations made before the transition date", "Setting cumulative translation differences of foreign operations to zero"], answer: 0, explanation: "Ind AS 101 (D7AA) allows previous GAAP carrying amounts as deemed cost, with decommissioning adjustments; the others are also in IFRS 1." },
    { id: "fr-101", chapter: "14. Ind AS 101 \"First-time Adoption of Ind AS\"", prompt: "A first-time adopter chooses to restate a business combination that took place before the transition date. Under Ind AS 101, it must:", options: ["restate only that combination", "restate all earlier business combinations as well", "restate all business combinations ever made", "restate all later business combinations as well"], answer: 3, explanation: "If any past business combination is restated under Ind AS 103, all later business combinations must also be restated." },
    { id: "fr-102", chapter: "15. Analysis of Financial Statements", prompt: "A company's leases were previously operating leases (rent expensed). On applying Ind AS 116 as lessee, its EBITDA and debt-equity ratio will typically:", options: ["both decrease", "both increase", "EBITDA decreases, debt-equity increases", "EBITDA increases, debt-equity decreases"], answer: 1, explanation: "Rent is replaced by depreciation and interest (both below EBITDA), and lease liabilities add to debt." },
    { id: "fr-103", chapter: "15. Analysis of Financial Statements", prompt: "While reviewing a company's Ind AS financial statements, you find a final equity dividend proposed by the board after year end shown as a current liability. The correct view is:", options: ["It is correct, as the proposal relates to the year's profits", "It is wrong; it is not a liability at year end and is only disclosed", "It is correct, provided the shareholders later approve the dividend", "It is wrong; it should be presented in OCI as an appropriation"], answer: 1, explanation: "Under Ind AS 10, dividends declared after the reporting period are not a present obligation at that date; they are disclosed in the notes." },
    { id: "fr-104", chapter: "15. Analysis of Financial Statements", prompt: "A company's statements show redeemable preference shares (mandatory redemption at a fixed date) within equity share capital. Correcting this misstatement under Ind AS 32 will:", options: ["reduce the debt-equity ratio, as preference capital is not debt", "have no effect on any ratio, as only presentation changes", "increase profit after tax, as dividends are no longer appropriations", "raise the debt-equity ratio, with the dividends becoming finance cost"], answer: 3, explanation: "Mandatorily redeemable preference shares are financial liabilities; their dividends are interest expense, raising debt and reducing profit." },
    { id: "fr-105", chapter: "16. Professional and Ethical Duty of a Chartered Accountant", prompt: "A CA working as financial controller is told by the CFO that she will lose her bonus and possibly her job unless she delays recording an impairment until after a loan covenant test. This is primarily a:", options: ["self-review threat", "intimidation threat", "advocacy threat", "familiarity threat"], answer: 1, explanation: "Pressure from a superior through threats of dismissal or loss of rewards is an intimidation threat to compliance with integrity and objectivity." },
    { id: "fr-106", chapter: "16. Professional and Ethical Duty of a Chartered Accountant", prompt: "A CA in industry whose bonus depends on reported profit is responsible for estimating the warranty provision. Which threat does this mainly create?", options: ["Advocacy threat", "Self-review threat", "Self-interest threat", "Familiarity threat"], answer: 2, explanation: "A financial interest in the outcome of a judgement (a profit-linked bonus) is a self-interest threat to objectivity." },
    { id: "fr-107", chapter: "17. Accounting and Technology", prompt: "The main purpose of XBRL tagging in financial reporting is to:", options: ["encrypt financial statements so they cannot be altered after filing", "provide assurance on the data, replacing the statutory audit", "convert financial statements automatically into multiple languages", "make each data item machine-readable for automated comparison"], answer: 3, explanation: "XBRL attaches standard tags to each data item so software can read and compare it; it does not encrypt or assure the data." },
    { id: "fr-108", chapter: "17. Accounting and Technology", prompt: "Which feature of a blockchain-based ledger is most relevant to the idea of 'triple-entry' accounting?", options: ["Each transaction is posted three times within the entity's own books", "Each transaction is also recorded on a shared, tamper-evident ledger", "It removes the need for accounting estimates and management judgement", "It allows both parties to edit entries freely once they are recorded"], answer: 1, explanation: "Triple-entry adds a third, cryptographically secured record on a shared ledger to the two parties' own entries, making records hard to alter." }
  ]
};
export default bank;
